process::WFP Seed Assumptions.PrologProcedure:
#Region Seed WFP Assumptions — global planning drivers, per Period x Version x Entity
# Idempotent. Written at leaf entities only (Group is a consolidation; rates
# don't sum) — rules read at the position's Home Entity. Same values across all
# periods/versions/entities for now — edit per cell after where a driver should
# vary (e.g. Merit % by year).
cCube = 'WFP Assumptions';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

# measure ; value
vM =
'Merit Increase %;0.03~' |
'Promotion Budget %;0.01~' |
'Inflation %;0.025~' |
'Actuals Cutoff Index;15~' |
'Merit Review Index;16~' |
'Vacancy Allowance %;0.10~' |
'Standard FTE Hours;160~' |
'Bonus Pool %;0.10~' |
'Employer Oncost Fallback %;0.15~';

vVers = 'Budget|Working|Forecast|';
vEnts = 'UK Ltd|US Inc|NZ Ltd|';

nP = 1;
WHILE( nP <= nPcount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
      vVl = vVers;
      WHILE( SCAN( '|', vVl ) > 1 );
         nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
         vEl = vEnts;
         WHILE( SCAN( '|', vEl ) > 1 );
            nS = SCAN( '|', vEl ); vEnt = SUBST( vEl, 1, nS - 1 ); vEl = SUBST( vEl, nS + 1, LONG( vEl ) - nS );
            vRows = vM;
            WHILE( SCAN( '~', vRows ) > 1 );
               nS = SCAN( '~', vRows ); vRec = SUBST( vRows, 1, nS - 1 ) | ';'; vRows = SUBST( vRows, nS + 1, LONG( vRows ) - nS );
               nS = SCAN( ';', vRec ); vMeas = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
               nS = SCAN( ';', vRec ); nVal  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
               CellPutN( nVal, cCube, vPer, vVer, vEnt, vMeas );
            END;
         END;
      END;
   ENDIF;
   nP = nP + 1;
END;

process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary + One-Time per active month
# Budget = flat seed (the approved/frozen plan). Working = seed with the merit +
# promotion uplift applied from Merit Review Index. Actual = flat, plus the real
# EXEC-001 Jan-Mar raise. One-Time: a sample CS-001 retention payment in 2026-06.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';
cAsm  = 'WFP Assumptions';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vHome = ATTRS( cPos, vPos, 'Home Entity' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      # comp-action assumptions (flat across periods; read at the home entity)
      nMeritIdx = CellGetN( cAsm, '2026-01', 'Working', vHome, 'Merit Review Index' );
      nUplift   = CellGetN( cAsm, '2026-01', 'Working', vHome, 'Merit Increase %' )
                + CellGetN( cAsm, '2026-01', 'Working', vHome, 'Promotion Budget %' );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',  vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working', vPos, 'FTE' );

               # Working salary: flat until the review month, then uplifted
               nWkSal = nSal;
               IF( nPidx >= nMeritIdx );
                  nWkSal = nSal * ( 1 + nUplift );
               ENDIF;
               CellPutN( nWkSal, cCube, vPer, 'Working', vPos, 'Base Salary' );

               # Actual: mirrors flat seed, with the EXEC-001 raise for closed months
               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

# Sample one-time payment: CS-001 retention, 15,000 in 2026-06 (Budget + Working)
CellPutN( 15000, cCube, '2026-06', 'Budget',  'CS-001', 'One-Time Amount' );
CellPutN( 15000, cCube, '2026-06', 'Working', 'CS-001', 'One-Time Amount' );

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets the attribute VALUES that were originally built declaratively and so do not
# survive a deploy: WFP Period (index/days/prior/FY), WFP Job Family (Pay Index),
# WFP Entity, WFP Version, WFP Cost Centre. Idempotent — safe to re-run.

# --- WFP Period: Period Index (chronological), Days In Month, Prior Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   # leaf months are numeric elements named YYYY-MM
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 );
         nDays = 28;
      ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 );
         nDays = 30;
      ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' );
         AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' );
      ENDIF;
      IF( vPL @<> '' );
         AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' );
      ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type, Description ---
vVr = 'Actual;Input;Loaded from payroll~Budget;Snapshot;Approved plan (frozen)~Forecast;Calculated;Actual for closed months + Working for open~Working;Input;Live editable working version~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

process::WFP Seed Assumptions.PrologProcedure:
#Region Seed WFP Assumptions — planning drivers, per Period x Version x Entity
# Phase 3.5: each CALCULATED version carries its OWN complete assumption set.
#   Budget   = the approved/frozen plan: no merit, no promo, no bonus, no actuals
#              blend (Actuals Cutoff Index 0). Preserves the Phase 1/2 Budget
#              assertion suite.
#   Forecast = the working current model: 3% merit + 1% promo from review index
#              16, 10% bonus pool, actuals blend to index 15.
#   Downside = a self-contained cost-pressure scenario: 5% merit, 4% inflation,
#              12% bonus, faster fill (5% vacancy), actuals blend to index 15.
# Idempotent. Written at leaf entities only (Group is a consolidation). Rules read
# at the position's Home Entity. Edit per cell after where a driver varies by year.
cCube = 'WFP Assumptions';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

# measure ; Budget ; Forecast ; Downside
vM =
'Merit Increase %;0;0.03;0.05~' |
'Promotion Budget %;0;0.01;0.01~' |
'Inflation %;0.025;0.025;0.04~' |
'Actuals Cutoff Index;0;15;15~' |
'Merit Review Index;0;16;16~' |
'Vacancy Allowance %;0.10;0.10;0.05~' |
'Standard FTE Hours;160;160;160~' |
'Bonus Pool %;0;0.10;0.12~' |
'Employer Oncost Fallback %;0.15;0.15;0.15~';

vEnts = 'UK Ltd|US Inc|NZ Ltd|';

nP = 1;
WHILE( nP <= nPcount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
      vEl = vEnts;
      WHILE( SCAN( '|', vEl ) > 1 );
         nS = SCAN( '|', vEl ); vEnt = SUBST( vEl, 1, nS - 1 ); vEl = SUBST( vEl, nS + 1, LONG( vEl ) - nS );
         vRows = vM;
         WHILE( SCAN( '~', vRows ) > 1 );
            nS = SCAN( '~', vRows ); vRec = SUBST( vRows, 1, nS - 1 ) | ';'; vRows = SUBST( vRows, nS + 1, LONG( vRows ) - nS );
            nS = SCAN( ';', vRec ); vMeas = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nBud  = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nFcst = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
            nS = SCAN( ';', vRec ); nDwn  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
            CellPutN( nBud,  cCube, vPer, 'Budget',   vEnt, vMeas );
            CellPutN( nFcst, cCube, vPer, 'Forecast', vEnt, vMeas );
            CellPutN( nDwn,  cCube, vPer, 'Downside', vEnt, vMeas );
         END;
      END;
   ENDIF;
   nP = nP + 1;
END;

process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary + One-Time per active month
# Phase 3.5: seed every CALCULATED version from ITS OWN assumptions.
#   Budget   = flat (its Merit Review Index is 0, so no uplift; cutoff 0 so all
#              active months are "open" and get seeded).
#   Forecast = merit + promotion uplift from its own Merit Review Index / %.
#   Downside = uplift from its own (steeper) assumptions.
#   Actual   = flat seed, plus the real EXEC-001 Jan-Mar raise (a modelled actual
#              until the Phase 7 payroll load).
# Forecast / Downside CLOSED months (Period Index <= that version's Actuals Cutoff
# Index) are provided by the WFP Workforce Input rule (= Actual) and MUST NOT be
# written here — CellPutN to a ruled cell fails. This seed writes only their
# open-month input.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';
cAsm  = 'WFP Assumptions';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

vVers = 'Budget|Forecast|Downside|';

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE  = ATTRN( cPos, vPos, 'FTE' );
      nSal  = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vHome = ATTRS( cPos, vPos, 'Home Entity' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd   = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx   = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );

               vVl = vVers;
               WHILE( SCAN( '|', vVl ) > 1 );
                  nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );

                  nCutoff   = CellGetN( cAsm, '2026-01', vVer, vHome, 'Actuals Cutoff Index' );
                  nMeritIdx = CellGetN( cAsm, '2026-01', vVer, vHome, 'Merit Review Index' );
                  nUplift   = CellGetN( cAsm, '2026-01', vVer, vHome, 'Merit Increase %' )
                            + CellGetN( cAsm, '2026-01', vVer, vHome, 'Promotion Budget %' );

                  # only OPEN months for this version (closed months come from the rule)
                  IF( nPidx > nCutoff );
                     nVerSal = nSal;
                     IF( nMeritIdx > 0 & nPidx >= nMeritIdx );
                        nVerSal = nSal * ( 1 + nUplift );
                     ENDIF;
                     CellPutN( nFTE,    cCube, vPer, vVer, vPos, 'FTE' );
                     CellPutN( nVerSal, cCube, vPer, vVer, vPos, 'Base Salary' );
                  ENDIF;
               END;

               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

# Sample one-time payment: CS-001 retention, 15,000 in 2026-06 (open month).
# Forecast + Downside carry it; Budget is the frozen pre-comp-action plan.
CellPutN( 15000, cCube, '2026-06', 'Forecast', 'CS-001', 'One-Time Amount' );
CellPutN( 15000, cCube, '2026-06', 'Downside', 'CS-001', 'One-Time Amount' );

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets the attribute VALUES that were originally built declaratively and so do not
# survive a deploy: WFP Period (index/days/prior/FY), WFP Job Family (Pay Index),
# WFP Entity, WFP Version, WFP Cost Centre. Idempotent — safe to re-run.

# --- WFP Period: Period Index (chronological), Days In Month, Prior Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   # leaf months are numeric elements named YYYY-MM
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 );
         nDays = 28;
      ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 );
         nDays = 30;
      ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' );
         AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' );
      ENDIF;
      IF( vPL @<> '' );
         AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' );
      ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Frozen), Description ---
# Phase 3.5: Working removed. Actual/Budget/Forecast/Downside are all Calculated
# for now; Actual becomes Frozen at the Phase 7 payroll load. Snapshot members
# (FCST YYYY-MM, Budget FINAL) are set to Frozen by WFP Snapshot Version.
vVr = 'Actual;Calculated;Modelled actual — becomes Frozen at the Phase 7 payroll load~Budget;Calculated;Approved plan being built — snapshot to Budget FINAL at lock~Forecast;Calculated;Working current model — closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — freeze a calculating version into a Frozen member
# Phase 3.5. Copies the INPUT layer (Workforce Input, Assumptions, FX Rates, Pay
# Rates) of pSource into pTarget; Workforce Cost + Headcount then calculate for
# pTarget to exactly the pSource picture and stay there while the inputs are
# untouched. pTarget is created if absent and marked Version Type = Frozen.
# Run at month-end close (pSource = Forecast) or budget lock (pSource = Budget).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   # create the target member if needed (Direct = committed immediately), mark Frozen
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Frozen', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' — ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );

   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 );
                        CellPutN( nVal, cWI, vP, pTarget, vPos, vM );
                        nCopied = nCopied + 1;
                     ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 );
                        CellPutN( nVal, cAS, vP, pTarget, vEnt, vM );
                        nCopied = nCopied + 1;
                     ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 );
                              CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM );
                              nCopied = nCopied + 1;
                           ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 );
                                    CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM );
                                    nCopied = nCopied + 1;
                                 ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' input cells copied. Cost + Headcount recalculate for ' | pTarget | '.' );
ENDIF;
